package com.aaliyun.leadnews.ai;import com.aaliyun.leadnews.ai.exception.AiExceptions;import com.aaliyun.leadnews.ai.support.AiCallExecutor;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.concurrent.atomic.AtomicInteger;import static org.assertj.core.api.Assertions.*;
class RetryPolicyTest {@Test void retriesTransientOnce(){AtomicInteger n=new AtomicInteger();try(var x=new AiCallExecutor(TestFixtures.properties(Duration.ofSeconds(1),1,1))){assertThat(x.execute(()->{if(n.getAndIncrement()==0)throw new RuntimeException("HTTP 503");return "ok";})).isEqualTo("ok");assertThat(n).hasValue(2);}}@Test void doesNotRetryAuthentication(){AtomicInteger n=new AtomicInteger();try(var x=new AiCallExecutor(TestFixtures.properties(Duration.ofSeconds(1),2,1))){assertThatThrownBy(()->x.execute(()->{n.incrementAndGet();throw new RuntimeException("HTTP 401");})).isInstanceOf(AiExceptions.ProviderUnavailable.class);assertThat(n).hasValue(1);}}}
